def shortestPathBinaryMatrix(grid):
    from collections import deque
    n = len(grid)
    if grid[0][0] or grid[-1][-1]:
        return -1
    q, seen = deque([(0, 0, 1)]), {(0, 0)}
    while q:
        x, y, d = q.popleft()
        if (x, y) == (n - 1, n - 1):
            return d
        for dx in (-1, 0, 1):
            for dy in (-1, 0, 1):
                a, b = x + dx, y + dy
                if 0 <= a < n and 0 <= b < n and not grid[a][b] and (a, b) not in seen:
                    seen.add((a, b))
                    q.append((a, b, d + 1))
    return -1

