def characterReplacement(s, k):
    from collections import defaultdict
    cnt, l, mx, best = defaultdict(int), 0, 0, 0
    for r, c in enumerate(s):
        cnt[c] += 1
        mx = max(mx, cnt[c])
        while r - l + 1 - mx > k:
            cnt[s[l]] -= 1; l += 1
        best = max(best, r - l + 1)
    return best

