def checkInclusion(s1, s2):
    from collections import Counter
    n = len(s1)
    if n > len(s2):
        return False
    need = Counter(s1)
    win = Counter(s2[:n])
    if win == need:
        return True
    for i in range(n, len(s2)):
        win[s2[i]] += 1
        win[s2[i - n]] -= 1
        if win[s2[i - n]] == 0:
            del win[s2[i - n]]
        if win == need:
            return True
    return False

